-- 字段编码为 ASCII（E11-T09 导入工具口径，OQ-72）；附录原表列名（中文）完整保留在 help_text「原表列名「…」」。
-- 表单：A_BASELINE 基线档案（分类 1–8，212 字段 + 出生日期）与 A_ANNUAL_FU 年度随访记录
--   （分类 9，54 字段；随访四分组 A-FLD-007）。#217 死亡随访时间与 #216 死亡日期按 Q22 合并为同一
--   字段：登记在册但停用（停用不进模板下发与校验），导入两列不一致报警告随 E18。
-- 替换 V28 / V31 / V33 / V36 的演示种子（示例字段、yesno 选项集、演示规则与记录）：
--   演示记录及其字段历史一并清理（全部虚构数据，规则 5）；v1 版本快照按 V29 同款重建。
-- fe_field.carry_over / dict_code 列与 FormSchema 下发随 E21-T04 字段字典录入配套迁移（OQ-67① / OQ-69④）。

-- ① 清理演示种子（V28 演示表单 A_BASELINE 的字段 / 选项集 / 规则 / 记录与快照）
DELETE fh FROM fe_field_history fh
  JOIN fe_record r ON fh.record_type = 'FE_RECORD' AND fh.record_id = r.id
 WHERE r.form_code = 'A_BASELINE';
DELETE FROM fe_record WHERE form_code = 'A_BASELINE';
DELETE FROM fe_form_version_field WHERE form_code = 'A_BASELINE';
DELETE FROM fe_form_version WHERE form_code = 'A_BASELINE';
DELETE FROM fe_field WHERE form_code = 'A_BASELINE';
DELETE FROM fe_rule WHERE form_code = 'A_BASELINE';
DELETE FROM fe_option WHERE set_code = 'yesno';
DELETE FROM fe_option_set WHERE code = 'yesno';

-- ② 表单与分类（9 个分类概览 / 随访四分组，锚点键稳定）
UPDATE fe_form SET name = '基线档案', current_version = 1, categories = JSON_ARRAY(
  JSON_OBJECT('key', 'basic', 'label', '基本信息', 'sortNo', 10),
  JSON_OBJECT('key', 'case', 'label', '病例基本信息', 'sortNo', 20),
  JSON_OBJECT('key', 'lab', 'label', '实验室检查', 'sortNo', 30),
  JSON_OBJECT('key', 'echo', 'label', '超声检查', 'sortNo', 40),
  JSON_OBJECT('key', 'angio', 'label', '术前造影', 'sortNo', 50),
  JSON_OBJECT('key', 'surgery', 'label', '手术信息', 'sortNo', 60),
  JSON_OBJECT('key', 'periop', 'label', '围手术期', 'sortNo', 70),
  JSON_OBJECT('key', 'discharge_med', 'label', '出院带药', 'sortNo', 80)) WHERE code = 'A_BASELINE';

